// @pit: {"label": "Inspect repo layout and git state before saving the report"}
async ({ workspace: { list, glob }, git: { status, log } }) => {
  const [root, md, st, lg] = await Promise.all([list("."), glob(["reports/**", "analysis/**", "research/**"], { limit: 20 }), status(["--short"]), log(["--oneline", "-5"])]);
  return { root, md, st: st.stdout, lg: lg.stdout } as any;
}
